using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Infrastructure;
using Microsoft.EntityFrameworkCore.Metadata;
using Microsoft.EntityFrameworkCore.Migrations;
using Microsoft.EntityFrameworkCore.Migrations.Operations;
using Microsoft.Extensions.Configuration;
using Rask.Data;
using Rask.Values;

namespace Rask.SqlServer.Tests;

/// <summary>
///     An app whose last migration was added before Rask held its own times as moments: the snapshot of every battery
///     table as Rask 4333eba32 built it on SQL Server (BeforeTimestampsSqlServerModelSnapshot, generated by EF Core).
/// </summary>
public sealed class BeforeTimestampsContext(DbContextOptions<RaskAppDbContext> options) : RaskAppDbContext(options);

/// <summary>
///     Rask always wrote its own times in UTC, so holding them as a <see cref="Timestamp" /> changes the CLR type only:
///     the first migration after it has no operation for them, and above all no rewrite of their rows.
/// </summary>
public sealed class TimestampMigrationTests
{
    private static readonly IServiceProvider Services = new ConfigurationServices(new ConfigurationBuilder()
        .AddInMemoryCollection(new Dictionary<string, string?> { ["Rask:ConnectionStrings:App"] = "Server=unused;Database=unused" }).Build());

    [Fact]
    public void The_first_migration_after_rask_s_times_became_timestamps_rewrites_and_alters_none_of_them()
    {
        using var context = new BeforeTimestampsContext(new DbContextOptionsBuilder<RaskAppDbContext>().UseRaskSqlServer(Services).Options);
        var snapshot = context.GetService<IModelRuntimeInitializer>().Initialize(
            context.GetService<IMigrationsAssembly>().ModelSnapshot!.Model, designTime: true, validationLogger: null);
        var model = context.GetService<IDesignTimeModel>().Model;

        var operations = context.GetService<IMigrationsModelDiffer>().GetDifferences(snapshot.GetRelationalModel(), model.GetRelationalModel());
        var commands = context.GetService<IMigrationsSqlGenerator>().Generate(operations, model);

        var times = model.GetEntityTypes()
            .SelectMany(e => e.GetProperties().Where(p => p.ClrType == typeof(Timestamp)).Select(p => (e.GetTableName()!, p.GetColumnName())))
            .ToHashSet();
        Assert.Contains(times, t => t.Item2 == "RunAt");
        Assert.All(model.GetEntityTypes().SelectMany(e => e.GetProperties()).Where(p => p.ClrType == typeof(Timestamp)),
            p => Assert.Null(p.FindAnnotation(MomentsInUtc.Annotation)));
        Assert.DoesNotContain(commands, c => c.CommandText.Contains("UPDATE", StringComparison.Ordinal));
        Assert.DoesNotContain(operations, o => o is ColumnOperation c && times.Contains((c.Table, c.Name)));
    }

    // Just the configuration: that is all UseRaskSqlServer asks the provider for.
    private sealed class ConfigurationServices(IConfiguration configuration) : IServiceProvider
    {
        public object? GetService(Type serviceType) => serviceType == typeof(IConfiguration) ? configuration : null;
    }
}
